import * as T from './vendor/three.module.js';
export function updateWorldIncidents(w,s,dt){w.floorEvents??=new Map();const present=new Set();for(const item of[...(s.litter||[]),...(s.coins||[])]){present.add(item.id);let g=w.floorEvents.get(item.id);if(!g){g=new T.Group();g.position.set(item.x,.105,item.z);w.scene.add(g);w.floorEvents.set(item.id,g);if(item.value){const m=new T.Mesh(new T.CylinderGeometry(.095,.095,.018,16),new T.MeshStandardMaterial({color:0xe7ba4f,emissive:0xc68c20,emissiveIntensity:.7,metalness:.75,roughness:.3}));m.rotation.z=Math.PI/2;m.userData.target={id:'coin',key:item.id};g.add(m);const pts=[];for(let i=0;i<14;i++)pts.push(Math.sin(i*2.4)*.18,.02+(i%5)*.065,Math.cos(i*2.4)*.18);const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(pts,3));g.add(new T.Points(geo,new T.PointsMaterial({color:0xffd877,size:.018,transparent:true,opacity:.8,depthWrite:false,blending:T.AdditiveBlending})));}else if(item.type==='paper'){for(let i=0;i<3;i++){const m=w.box((i-1)*.1,.012+i*.008,0,.18,.008,.15,w.a.get('paper',0xada78a),false,g,{id:'litter',key:item.id});m.rotation.set(.1*i,.6*i,.1*i);}}else{const m=new T.Mesh(new T.CircleGeometry(.30,13),new T.MeshStandardMaterial({color:0x4e3924,transparent:true,opacity:.78,roughness:.45,depthWrite:false}));m.rotation.x=-Math.PI/2;m.scale.y=.6;m.userData.target={id:'litter',key:item.id};g.add(m);}}
 if(item.value){g.position.y=.21+Math.sin(s.time*2.3)*.035;g.children[0].rotation.y=s.time*.9;g.children[1].rotation.y=-s.time*.6;}}
 for(const[id,g]of w.floorEvents)if(!present.has(id)){w.scene.remove(g);g.traverse(o=>{o.geometry?.dispose();if(o.isPoints)o.material.dispose();});w.floorEvents.delete(id);}
 if(w.heldBoard){const progress=s.boardBuild?.time||0;w.heldBoard.rotation.z=s.boardBuild?Math.sin(progress*28)*.04:0;w.heldBoard.position.y=s.boardBuild?-.20+Math.sin(progress*28)*.025:-.30;}
}
